function industryValueChart(){const labels=['2023','2024','2025','2026','2027','2028'],actual=[67,62,58],forecast=[null,null,null,55,55,55],w=900,h=330,p={l:48,r:26,t:34,b:38},x=i=>p.l+i*(w-p.l-p.r)/(labels.length-1),y=v=>p.t+(70-v)*(h-p.t-p.b)/70,actualPts=actual.map((v,i)=>`${x(i)},${y(v)}`).join(' '),futurePts=forecast.map((v,i)=>v===null?null:`${x(i)},${y(v)}`).filter(Boolean).join(' ');return `<div class="industry-chart"><div class="chart-legend"><span><i class="legend-blue"></i>实际产值</span><span><i class="legend-green"></i>预测产值</span></div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="内蒙古产业链产值趋势，单位亿元"><text x="8" y="${p.t}" fill="#7d899c" font-size="12">亿元</text>${[0,10,20,30,40,50,60,70].map(v=>`<line x1="${p.l}" y1="${y(v)}" x2="${w-p.r}" y2="${y(v)}" stroke="#e9edf3"/><text x="${p.l-12}" y="${y(v)+4}" text-anchor="end" fill="#8994a6" font-size="11">${v}</text>`).join('')}<polygon points="${actualPts} ${x(2)},${h-p.b} ${x(0)},${h-p.b}" fill="#2f6fdf" opacity=".06"/><polyline points="${actualPts}" fill="none" stroke="#2f6fdf" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${futurePts}" fill="none" stroke="#16a38a" stroke-width="3" stroke-dasharray="9 6" stroke-linecap="round"/>${actual.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="white" stroke="#2f6fdf" stroke-width="2"/>`).join('')}${forecast.map((v,i)=>v===null?'':`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="white" stroke="#16a38a" stroke-width="2"/>`).join('')}${labels.map((l,i)=>`<text x="${x(i)}" y="${h-10}" text-anchor="middle" fill="#8994a6" font-size="11">${l}</text>`).join('')}</svg></div>`}
function insight(){const cities=[['呼和浩特',51855],['鄂尔多斯',36100],['包头',26920],['赤峰',24200],['通辽',14500],['呼伦贝尔',12200],['巴彦淖尔',11500],['乌兰察布',11000],['锡林郭勒盟',10400],['兴安盟',7180],['乌海',6400],['阿拉善盟',4200]];const terms=['设备','销售','技术','运行','消防','设计','工程','系统','环保','工艺','合同','消防设施','电气','配电网','图纸','预算','检修','安全员','自动化','调度','检测','施工','工程质量','焊接','软件','市场','规划','仪表','报告','管理'];let jobRows=[...D.positions.map((p,i)=>({...p,stage:i<3?'上游':i<5?'中游':'下游'})),...['钣金工程师','钣金技工','材料研发工程师','财务总监','采购计划员','采购经理','仓储管理员','仓储技工'].map((name,i)=>({...D.positions[i%D.positions.length],name,stage:'上游'}))];let filtered=jobRows.filter(p=>(S.insightJobStage==='全部'||p.stage===S.insightJobStage)&&(!S.insightCity||p.city.includes(S.insightCity)||S.insightCity.includes(p.city.replace('市','')))),shown=S.insightJobExpanded?filtered:filtered.slice(0,8);return `<section class="card insight-panel"><div class="insight-heading"><h2>产业结构图谱关系图</h2><small>全国口径　104 节点 / 100 关系 · 力导向布局 · 点击节点查看详情</small></div><div class="insight-graph-controls"><select aria-label="产业链"><option>${I.industry}</option></select><div><button class="btn" data-action="insight-expand">${S.insightExpanded?'收起层级':'全部展开'}</button><button class="btn" data-action="insight-reset">重置</button></div></div><div class="insight-network"><svg viewBox="0 0 900 440" preserveAspectRatio="none" aria-hidden="true"><line x1="450" y1="84" x2="204" y2="240"/><line x1="450" y1="84" x2="450" y2="240"/><line x1="450" y1="84" x2="695" y2="240"/>${S.insightExpanded?'<line x1="204" y1="240" x2="105" y2="360"/><line x1="204" y1="240" x2="295" y2="360"/><line x1="695" y1="240" x2="610" y2="360"/><line x1="695" y1="240" x2="790" y2="360"/>':''}</svg><div class="insight-legend">● 产业链　<span>● 产业环节</span>　<em>● 二级环节</em></div>${[['城市生命线智慧运行',50,19,'purple'],['基础设施普查与改造',23,54,'teal'],['系统集成部署',50,54,'teal'],['检测与维护',77,54,'teal'],...(S.insightExpanded?[['供热管网更新改造',12,82,'orange'],['电气设施巡检',33,82,'orange'],['管网水质检测',68,82,'orange'],['设备状态监测',88,82,'orange']]:[])].map(x=>`<button class="insight-network-node ${x[3]} ${S.insightNode===x[0]?'selected':''}" style="left:${x[1]}%;top:${x[2]}%" data-action="insight-node" data-value="${x[0]}"><i></i><span>${x[0]}</span></button>`).join('')}</div><div class="insight-node-detail">${S.insightNode?`<b>${S.insightNode}</b><p>该节点连接产业链上下游环节，并关联企业与岗位样例。</p><button class="link" data-route="chain">查看关联企业 →</button>`:'<b>点击图谱节点</b><p>在此查看节点层级、上下游关系与关联企业。</p>'}</div></section><section class="card insight-filter-card"><div class="field"><label>省份</label><select><option>内蒙古自治区</option></select></div><div class="field"><label>城市（盟市）</label><select id="insight-city"><option value="">全部城市</option>${cities.map(c=>`<option value="${c[0]}" ${S.insightCity===c[0]?'selected':''}>${c[0]}</option>`).join('')}</select></div><p>当前区域 <b>${S.insightCity||'内蒙古自治区'}</b> · 筛选作用于下方产值、区域分布、热词与典型岗位　本区域典型岗位 <b>209</b> 个</p></section><section class="card insight-panel"><div class="insight-heading"><h2>产值规模柱线图</h2><small><span class="insight-filter-tag">随区域筛选</span> 当前区域「${S.insightCity||'内蒙古自治区'}」企业的产业链产值估算，万元折亿元。产值增减和岗位需求增幅不是同一口径。</small></div><div class="insight-growth">⌁　2023→2028（含预测）年均复合增长 -3.7%</div>${insightTrendChart()}</section><section class="card insight-panel"><div class="insight-heading"><h2>区域分布</h2><small><span class="insight-filter-tag">随区域筛选</span> 「内蒙古自治区」范围内的企业数与岗位需求</small></div><div class="insight-region-legend">当前筛选 12 个区域　 <span>● 关联企业（家）</span>　 <span>● 岗位需求（个）</span></div><div class="insight-region-chart">${cities.map(c=>`<button class="insight-region-row ${S.insightCity===c[0]?'active':''}" data-action="insight-city" data-value="${c[0]}"><span>${c[0]}</span><i style="width:${Math.round(c[1]/60000*100)}%"></i><em>${c[1].toLocaleString('zh-CN')}</em></button>`).join('')}</div></section><section class="card insight-panel"><div class="insight-heading"><h2>产业技术热词词云</h2><small><span class="insight-filter-tag">随区域筛选</span> 唯一词 57 个（岗位热词条目 150 条，同词已合并）· 词云展示热度 TOP 60</small></div><div class="insight-word-cloud">${terms.map((t,i)=>`<button style="font-size:${12+(i%5)*4}px;color:${['#2d6fda','#128f7b','#dc8d19','#77869e'][i%4]}" data-action="keyword" data-value="${t}">${t}</button>`).join('')}</div></section><section class="card insight-jobs"><div class="insight-jobs-head"><div><h2>产业侧典型岗位</h2><span>岗位清单　默认收口</span><p>209 个 · 中游 20 个 · 覆盖 10 个区域 · 已按「${S.insightCity||'内蒙古自治区'}」过滤</p></div><button class="btn" data-action="insight-jobs-expand">${S.insightJobExpanded?'收起岗位':'展开全部 209 个'}</button></div><div class="insight-job-tabs">${['全部','上游','中游','下游'].map((x,i)=>`<button class="${S.insightJobStage===x?'active':''}" data-action="insight-job-stage" data-value="${x}">${x}（${[209,59,20,129][i]}）</button>`).join('')}</div>${table(['岗位名称','所属岗位群','产业链层级','相关区域'],shown.map(p=>row([`<button class="link" data-action="job-open" data-value="${p.id}">${p.name} ↗</button>`,p.group,tag(p.stage,p.stage==='上游'?'orange':'gray'),S.insightCity||p.city])))}<button class="insight-show-more" data-action="insight-jobs-expand">${S.insightJobExpanded?'收起岗位':'⌄ 展开全部 209 个岗位'}</button></section>`}
function insightTrendChart(){let years=[2023,2024,2025,2026,2027,2028],values=[67,62,58,55.4,55.4,55.5],growth=[null,-8,-6,-4,0,.5],w=900,h=310,l=44,r=44,t=34,b=34,xx=i=>l+i*(w-l-r)/6+(w-l-r)/12,yy=v=>t+(70-v)*(h-t-b)/70,gy=v=>t+(2-v)*(h-t-b)/12;return `<div class="insight-trend"><div class="insight-legend"><span>■ 产值实际</span><span>▣ 产值预测</span><span>○ 增长率实际</span><span>◌ 增长率预测</span></div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="2023 至 2028 年产值和增长率混合图">${[0,10,20,30,40,50,60,70].map(v=>`<line x1="${l}" x2="${w-r}" y1="${yy(v)}" y2="${yy(v)}" stroke="#e9edf3"/><text x="${l-12}" y="${yy(v)+4}" text-anchor="end" fill="#8994a6" font-size="11">${v}</text>`).join('')}${values.map((v,i)=>`<rect x="${xx(i)-14}" y="${yy(v)}" width="28" height="${h-b-yy(v)}" rx="2" fill="${i<3?'#2f6fdf':'#b8cbed'}" stroke="${i<3?'none':'#5c88d5'}" stroke-dasharray="${i<3?'none':'4 2'}"><title>${years[i]}年产值 ${v} 亿元</title></rect><text x="${xx(i)}" y="${h-9}" text-anchor="middle" fill="#8390a3" font-size="11">${years[i]}年</text>`).join('')}<polyline points="${[1,2].map(i=>`${xx(i)},${gy(growth[i])}`).join(' ')}" fill="none" stroke="#10a58c" stroke-width="2"/><polyline points="${[3,4,5].map(i=>`${xx(i)},${gy(growth[i])}`).join(' ')}" fill="none" stroke="#10a58c" stroke-width="2" stroke-dasharray="7 5"/>${growth.map((v,i)=>v===null?'':`<circle cx="${xx(i)}" cy="${gy(v)}" r="3" fill="white" stroke="#10a58c" stroke-width="2"><title>${years[i]}年增长率 ${v}%</title></circle>`).join('')}${[-10,-8,-6,-4,-2,0,2].map(v=>`<text x="${w-r+8}" y="${gy(v)+4}" fill="#8994a6" font-size="11">${v}%</text>`).join('')}</svg></div>`}
if(location.hash&&FEATURE_IDS.includes(location.hash.slice(1))){S.active=location.hash.slice(1);(navAncestors(NAV,S.active)||[]).forEach(k=>S.collapsedNav[k]=false)}render();


